import{_ as a,H as s,f as t,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"11丨SQL99是如何使用连接的，与SQL92的区别是什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"SQL99标准中的连接查询","slug":"sql99标准中的连接查询","link":"#sql99标准中的连接查询","children":[{"level":3,"title":"交叉连接","slug":"交叉连接","link":"#交叉连接","children":[]},{"level":3,"title":"自然连接","slug":"自然连接","link":"#自然连接","children":[]},{"level":3,"title":"ON连接","slug":"on连接","link":"#on连接","children":[]},{"level":3,"title":"USING连接","slug":"using连接","link":"#using连接","children":[]},{"level":3,"title":"外连接","slug":"外连接","link":"#外连接","children":[]},{"level":3,"title":"自连接","slug":"自连接","link":"#自连接","children":[]}]},{"level":2,"title":"SQL99和SQL92的区别","slug":"sql99和sql92的区别","link":"#sql99和sql92的区别","children":[]},{"level":2,"title":"不同DBMS中使用连接需要注意的地方","slug":"不同dbms中使用连接需要注意的地方","link":"#不同dbms中使用连接需要注意的地方","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"SQL必知必会/11丨SQL99是如何使用连接的，与SQL92的区别是什么？.md","filePath":"SQL必知必会/11丨SQL99是如何使用连接的，与SQL92的区别是什么？.md","lastUpdated":1779816304000}'),p={name:"SQL必知必会/11丨SQL99是如何使用连接的，与SQL92的区别是什么？.md"};function n(l,e,o,h,c,r){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="_11丨sql99是如何使用连接的-与sql92的区别是什么" tabindex="-1">11丨SQL99是如何使用连接的，与SQL92的区别是什么？ <a class="header-anchor" href="#_11丨sql99是如何使用连接的-与sql92的区别是什么" aria-label="Permalink to &quot;11丨SQL99是如何使用连接的，与SQL92的区别是什么？&quot;">​</a></h1><p>上节课我们讲解了SQL92标准，在它之后又提出了SQL99标准。现在各大DBMS中对SQL99标准的支持度更好。你一定听说过LEFT JOIN、RIGHT JOIN这样的操作符，这实际上就是SQL99的标准，在SQL92中它们是用（+）代替的。SQL92和SQL99标准原理类似，只是SQL99标准的可读性更强。</p><p>今天我就来讲解一下SQL99标准中的连接查询，在今天的课程中你需要重点掌握以下几方面的内容：</p><ol><li>SQL99标准下的连接查询是如何操作的？</li><li>SQL99与SQL92的区别是什么？</li><li>在不同的DBMS中，使用连接需要注意什么？</li></ol><h2 id="sql99标准中的连接查询" tabindex="-1">SQL99标准中的连接查询 <a class="header-anchor" href="#sql99标准中的连接查询" aria-label="Permalink to &quot;SQL99标准中的连接查询&quot;">​</a></h2><p>上一篇文章中，我用NBA球员的数据表进行了举例，包括了三张数据表player、team和height_grades。</p><p>其中player表为球员表，一共有37个球员，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/ee9b554ecbc296e1a5865b52d4bb3c99.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/ee9b554ecbc296e1a5865b52d4bb3c99.png" alt=""></a></p><p>team表为球队表，一共有3支球队，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/aa73203c43672b6d3be44748b1556075.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/aa73203c43672b6d3be44748b1556075.png" alt=""></a></p><p>height_grades表为身高等级表，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/4b5b2c666705364b793329b728a1ed37.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/4b5b2c666705364b793329b728a1ed37.png" alt=""></a></p><p>接下来我们看下在SQL99标准中，是如何进行连接查询的？</p><h3 id="交叉连接" tabindex="-1">交叉连接 <a class="header-anchor" href="#交叉连接" aria-label="Permalink to &quot;交叉连接&quot;">​</a></h3><p>交叉连接实际上就是SQL92中的笛卡尔乘积，只是这里我们采用的是CROSS JOIN。</p><p>我们可以通过下面这行代码得到player和team这两张表的笛卡尔积的结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL: SELECT * FROM player CROSS JOIN team</span></span></code></pre></div><p>运行结果（一共37*3=111条记录）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/95c97414eca15373f26ae2b4192880d2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/95c97414eca15373f26ae2b4192880d2.png" alt=""></a></p><p>如果多张表进行交叉连接，比如表t1，表t2，表t3进行交叉连接，可以写成下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL: SELECT * FROM t1 CROSS JOIN t2 CROSS JOIN t3</span></span></code></pre></div><h3 id="自然连接" tabindex="-1">自然连接 <a class="header-anchor" href="#自然连接" aria-label="Permalink to &quot;自然连接&quot;">​</a></h3><p>你可以把自然连接理解为SQL92中的等值连接。它会帮你自动查询两张连接表中所有相同的字段，然后进行等值连接。</p><p>如果我们想把player表和team表进行等值连接，相同的字段是team_id。还记得在SQL92标准中，是如何编写的么？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT player_id, a.team_id, player_name, height, team_name FROM player as a, team as b WHERE a.team_id = b.team_id</span></span></code></pre></div><p>在SQL99中你可以写成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT player_id, team_id, player_name, height, team_name FROM player NATURAL JOIN team</span></span></code></pre></div><p>实际上，在SQL99中用NATURAL JOIN替代了 <code>WHERE player.team_id = team.team_id</code>。</p><h3 id="on连接" tabindex="-1">ON连接 <a class="header-anchor" href="#on连接" aria-label="Permalink to &quot;ON连接&quot;">​</a></h3><p>ON连接用来指定我们想要的连接条件，针对上面的例子，它同样可以帮助我们实现自然连接的功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT player_id, player.team_id, player_name, height, team_name FROM player JOIN team ON player.team_id = team.team_id</span></span></code></pre></div><p>这里我们指定了连接条件是 <code>ON player.team_id = team.team_id</code>，相当于是用ON进行了team_id字段的等值连接。</p><p>当然你也可以ON连接进行非等值连接，比如我们想要查询球员的身高等级，需要用player和height_grades两张表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL99：SELECT p.player_name, p.height, h.height_level</span></span>
<span class="line"><span>FROM player as p JOIN height_grades as h</span></span>
<span class="line"><span>ON height BETWEEN h.height_lowest AND h.height_highest</span></span></code></pre></div><p>这个语句的运行结果和我们之前采用SQL92标准的查询结果一样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL92：SELECT p.player_name, p.height, h.height_level</span></span>
<span class="line"><span>FROM player AS p, height_grades AS h</span></span>
<span class="line"><span>WHERE p.height BETWEEN h.height_lowest AND h.height_highest</span></span></code></pre></div><p>一般来说在SQL99中，我们需要连接的表会采用JOIN进行连接，ON指定了连接条件，后面可以是等值连接，也可以采用非等值连接。</p><h3 id="using连接" tabindex="-1">USING连接 <a class="header-anchor" href="#using连接" aria-label="Permalink to &quot;USING连接&quot;">​</a></h3><p>当我们进行连接的时候，可以用USING指定数据表里的同名字段进行等值连接。比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT player_id, team_id, player_name, height, team_name FROM player JOIN team USING(team_id)</span></span></code></pre></div><p>你能看出与自然连接NATURAL JOIN不同的是，USING指定了具体的相同的字段名称，你需要在USING的括号()中填入要指定的同名字段。同时使用JOIN USING可以简化JOIN ON的等值连接，它与下面的SQL查询结果是相同的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT player_id, player.team_id, player_name, height, team_name FROM player JOIN team ON player.team_id = team.team_id</span></span></code></pre></div><h3 id="外连接" tabindex="-1">外连接 <a class="header-anchor" href="#外连接" aria-label="Permalink to &quot;外连接&quot;">​</a></h3><p>SQL99的外连接包括了三种形式：</p><ol><li>左外连接：LEFT JOIN 或 LEFT OUTER JOIN</li><li>右外连接：RIGHT JOIN 或 RIGHT OUTER JOIN</li><li>全外连接：FULL JOIN 或 FULL OUTER JOIN</li></ol><p>我们在SQL92中讲解了左外连接、右外连接，在SQL99中还有全外连接。全外连接实际上就是左外连接和右外连接的结合。在这三种外连接中，我们一般省略OUTER不写。</p><p>1.左外连接</p><p><strong>SQL92</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM player, team where player.team_id = team.team_id(+)</span></span></code></pre></div><p><strong>SQL99</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM player LEFT JOIN team ON player.team_id = team.team_id</span></span></code></pre></div><p>2.右外连接</p><p><strong>SQL92</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM player, team where player.team_id(+) = team.team_id</span></span></code></pre></div><p><strong>SQL99</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM player RIGHT JOIN team ON player.team_id = team.team_id</span></span></code></pre></div><p>3.全外连接</p><p><strong>SQL99</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM player FULL JOIN team ON player.team_id = team.team_id</span></span></code></pre></div><p>需要注意的是MySQL不支持全外连接，否则的话全外连接会返回左表和右表中的所有行。当表之间有匹配的行，会显示内连接的结果。当某行在另一个表中没有匹配时，那么会把另一个表中选择的列显示为空值。</p><p>也就是说，全外连接的结果=左右表匹配的数据+左表没有匹配到的数据+右表没有匹配到的数据。</p><h3 id="自连接" tabindex="-1">自连接 <a class="header-anchor" href="#自连接" aria-label="Permalink to &quot;自连接&quot;">​</a></h3><p>自连接的原理在SQL92和SQL99中都是一样的，只是表述方式不同。</p><p>比如我们想要查看比布雷克·格里芬身高高的球员都有哪些，在两个SQL标准下的查询如下。</p><p><strong>SQL92</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT b.player_name, b.height FROM player as a , player as b WHERE a.player_name = &#39;布雷克-格里芬&#39; and a.height &amp;lt; b.height</span></span></code></pre></div><p><strong>SQL99</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT b.player_name, b.height FROM player as a JOIN player as b ON a.player_name = &#39;布雷克-格里芬&#39; and a.height &amp;lt; b.height</span></span></code></pre></div><p>运行结果（6条记录）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/c79ecee3e5368ee73bfe7edb8a80a6e0.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/c79ecee3e5368ee73bfe7edb8a80a6e0.png" alt=""></a></p><h2 id="sql99和sql92的区别" tabindex="-1">SQL99和SQL92的区别 <a class="header-anchor" href="#sql99和sql92的区别" aria-label="Permalink to &quot;SQL99和SQL92的区别&quot;">​</a></h2><p>至此我们讲解完了SQL92和SQL99标准下的连接查询，它们都对连接进行了定义，只是操作的方式略有不同。我们再来回顾下，这些连接操作基本上可以分成三种情况：</p><ol><li>内连接：将多个表之间满足连接条件的数据行查询出来。它包括了等值连接、非等值连接和自连接。</li><li>外连接：会返回一个表中的所有记录，以及另一个表中匹配的行。它包括了左外连接、右外连接和全连接。</li><li>交叉连接：也称为笛卡尔积，返回左表中每一行与右表中每一行的组合。在SQL99中使用的CROSS JOIN。</li></ol><p>不过SQL92在这三种连接操作中，和SQL99还存在着明显的区别。</p><p>首先我们看下SQL92中的WHERE和SQL99中的JOIN。</p><p>你能看出在SQL92中进行查询时，会把所有需要连接的表都放到FROM之后，然后在WHERE中写明连接的条件。而SQL99在这方面更灵活，它不需要一次性把所有需要连接的表都放到FROM之后，而是采用JOIN的方式，每次连接一张表，可以多次使用JOIN进行连接。</p><p>另外，我建议多表连接使用SQL99标准，因为层次性更强，可读性更强，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT ...</span></span>
<span class="line"><span>FROM table1</span></span>
<span class="line"><span>    JOIN table2 ON table1和table2的连接条件</span></span>
<span class="line"><span>        JOIN table3 ON table2和table3的连接条件</span></span></code></pre></div><p>它的嵌套逻辑类似我们使用的FOR循环：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for t1 in table1:</span></span>
<span class="line"><span>    for t2 in table2:</span></span>
<span class="line"><span>       if condition1:</span></span>
<span class="line"><span>           for t3 in table3:</span></span>
<span class="line"><span>              if condition2:</span></span>
<span class="line"><span>                  output t1 + t2 + t3</span></span></code></pre></div><p>SQL99采用的这种嵌套结构非常清爽，即使再多的表进行连接也都清晰可见。如果你采用SQL92，可读性就会大打折扣。</p><p>最后一点就是，SQL99在SQL92的基础上提供了一些特殊语法，比如NATURAL JOIN和JOIN USING。它们在实际中是比较常用的，省略了ON后面的等值条件判断，让SQL语句更加简洁。</p><h2 id="不同dbms中使用连接需要注意的地方" tabindex="-1">不同DBMS中使用连接需要注意的地方 <a class="header-anchor" href="#不同dbms中使用连接需要注意的地方" aria-label="Permalink to &quot;不同DBMS中使用连接需要注意的地方&quot;">​</a></h2><p>SQL连接具有通用性，但是不同的DBMS在使用规范上会存在差异，在标准支持上也存在不同。在实际工作中，你需要参考你正在使用的DBMS文档，这里我整理了一些需要注意的常见的问题。</p><p><strong>1.不是所有的DBMS都支持全外连接</strong></p><p>虽然SQL99标准提供了全外连接，但不是所有的DBMS都支持。不仅MySQL不支持，Access、SQLite、MariaDB等数据库软件也不支持。不过在Oracle、DB2、SQL Server中是支持的。</p><p><strong>2.Oracle没有表别名AS</strong></p><p>为了让SQL查询语句更简洁，我们经常会使用表别名AS，不过在Oracle中是不存在AS的，使用表别名的时候，直接在表名后面写上表别名即可，比如player p，而不是player AS p。</p><p><strong>3.SQLite的外连接只有左连接</strong></p><p>SQLite是一款轻量级的数据库软件，在外连接上只支持左连接，不支持右连接，不过如果你想使用右连接的方式，比如 <code>table1 RIGHT JOIN table2</code>，在SQLite你可以写成 <code>table2 LEFT JOIN table1</code>，这样就可以得到相同的效果。</p><p>除了一些常见的语法问题，还有一些关于连接的性能问题需要你注意：</p><p><strong>1.控制连接表的数量</strong></p><p>多表连接就相当于嵌套for循环一样，非常消耗资源，会让SQL查询性能下降得很严重，因此不要连接不必要的表。在许多DBMS中，也都会有最大连接表的限制。</p><p><strong>2.在连接时不要忘记WHERE语句</strong></p><p>多表连接的目的不是为了做笛卡尔积，而是筛选符合条件的数据行，因此在多表连接的时候不要忘记了WHERE语句，这样可以过滤掉不必要的数据行返回。</p><p><strong>3.使用自连接而不是子查询</strong></p><p>我们在查看比布雷克·格里芬高的球员都有谁的时候，可以使用子查询，也可以使用自连接。一般情况建议你使用自连接，因为在许多DBMS的处理过程中，对于自连接的处理速度要比子查询快得多。你可以这样理解：子查询实际上是通过未知表进行查询后的条件判断，而自连接是通过已知的自身数据表进行条件判断，因此在大部分DBMS中都对自连接处理进行了优化。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>连接可以说是SQL中的核心操作，通过两篇文章的学习，你已经从多个维度对连接进行了了解。同时，我们对SQL的两个重要标准SQL92和SQL99进行了学习，在我们需要进行外连接的时候，建议采用SQL99标准，这样更适合阅读。</p><p>此外我还想强调一下，我们在进行连接的时候，使用的关系型数据库管理系统，之所以存在关系是因为各种数据表之间存在关联，它们并不是孤立存在的。在实际工作中，尤其是做业务报表的时候，我们会用到SQL中的连接操作（JOIN），因此我们需要理解和熟练掌握SQL标准中连接的使用，以及不同DBMS中对连接的语法规范。剩下要做的，就是通过做练习和实战来增强你的经验了，做的练习多了，也就自然有感觉了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/443181aea770ba5844efac6b02e02c5b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/105486/443181aea770ba5844efac6b02e02c5b.jpg" alt=""></a></p><p>我今天讲解了SQL99的连接操作，不妨请你做一个小练习。请你编写SQL查询语句，查询不同身高级别（对应height_grades表）对应的球员数量（对应player表）。</p><p>欢迎你在评论区写下你的答案，我会在评论区与你一起讨论。也欢迎把这篇文章分享给你的朋友或者同事。</p>`,103)])])}const b=a(p,[["render",n]]);export{g as __pageData,b as default};
